// Sidebar.jsx
import React, { useEffect, useMemo, useRef, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import ProfileMenu from "./ProfileMenu";
import ConfirmModal from "./ConfirmModal";

export default function Sidebar({
  sessions = [],
  onLoadSession = () => {},
  onNewChat = () => {},
}) {
  const [remoteSessions, setRemoteSessions] = useState([]);
  const [loadingRemote, setLoadingRemote] = useState(false);
  const [confirmState, setConfirmState] = useState({
    open: false,
    id: null,
    title: "",
    loading: false,
    error: null,
  });

  const historyRef = useRef(null);
  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    let mounted = true;
    setLoadingRemote(true);
    fetch("/api/sessions/list")
      .then((r) => (r.ok ? r.json() : Promise.reject("Failed to fetch")))
      .then((data) => {
        if (!mounted) return;
        if (Array.isArray(data)) setRemoteSessions(data);
        else setRemoteSessions([]);
      })
      .catch(() => setRemoteSessions([]))
      .finally(() => setLoadingRemote(false));
    return () => { mounted = false; };
  }, []);

  const mergedSessions = useMemo(() => {
    const map = new Map();
    (sessions || []).forEach((s) => { if (s && s.id) map.set(String(s.id), s); });
    (remoteSessions || []).forEach((rs) => { if (rs && rs.id && !map.has(String(rs.id))) map.set(String(rs.id), rs); });
    return Array.from(map.values()).slice(0, 50);
  }, [sessions, remoteSessions]);

  useEffect(() => {
    const el = historyRef.current;
    if (!el) return;
    const target = Math.max(0, el.scrollHeight - Math.round(el.clientHeight / 2));
    try {
      el.scrollTo({ top: target, behavior: "smooth" });
    } catch (e) {
      // fallback
      el.scrollTop = target;
    }
  }, [mergedSessions.length]);

  function openConfirm(id, title) {
    setConfirmState({ open: true, id, title, loading: false, error: null });
  }

  function closeConfirm() {
    setConfirmState({ open: false, id: null, title: "", loading: false, error: null });
  }

  async function handleConfirmDelete() {
    const id = confirmState.id;
    if (!id) return;
    setConfirmState((s) => ({ ...s, loading: true, error: null }));

    try {
      const resp = await fetch(`/api/sessions/${encodeURIComponent(id)}`, { method: "DELETE" });
      if (!resp.ok) {
        let text;
        try { text = await resp.text(); } catch (_) { text = `HTTP ${resp.status}`; }
        throw new Error(text || `Failed to delete session (status ${resp.status})`);
      }

      setRemoteSessions((rs) => rs.filter((r) => String(r.id) !== String(id)));

      try {
        const raw = localStorage.getItem("ai_chat_sessions");
        if (raw) {
          const arr = JSON.parse(raw);
          const filtered = (Array.isArray(arr) ? arr : []).filter((s) => String(s.id) !== String(id));
          localStorage.setItem("ai_chat_sessions", JSON.stringify(filtered));
        }
      } catch (e) {
        // ignore localStorage errors
      }

      closeConfirm();
      onNewChat();
      navigate("/");
    } catch (err) {
      setConfirmState((s) => ({ ...s, loading: false, error: String(err?.message || err) }));
    }
  }

  function summaryOf(s) {
    if (!s) return "";
    if (s.title) return s.title;
    if (s.prompt) {
      const words = String(s.prompt).trim().split(/\s+/);
      return words.slice(0, 6).join(" ") + (words.length > 6 ? "…" : "");
    }
    return `Trip ${new Date(s.createdAt || Date.now()).toLocaleString()}`;
  }

  return (
    <aside className="sidebar" aria-label="Chat history and navigation">
      <div className="sidebar-inner">
        <button
          className="btn-new"
          onClick={() => {
            onNewChat();
            navigate("/");
          }}
        >
          + New Chat
        </button>

        <div style={{ fontWeight: 700, color: "#0f172a", fontSize: 13, marginTop: 6 }}>Chat History</div>

        <div
          ref={historyRef}
          className="history-list"
          role="list"
          aria-label="Saved chat sessions"
        >
          {mergedSessions.length === 0 ? (
            <div className="empty">No saved chats yet</div>
          ) : (
            mergedSessions.slice(0, 12).map((s) => {
              const id = s.id ?? (s._id || Date.now());
              return (
                <div
                  key={id}
                  className="chat-row"
                  role="listitem"
                  tabIndex={0}
                  onClick={() => onLoadSession(s)}
                  onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") onLoadSession(s); }}
                  aria-label={`Open chat ${summaryOf(s)}`}
                >
                  <div className="chat-body">
                    <div className="chat-title">{summaryOf(s)}</div>
                    <div className="chat-sub">
                      {s.createdAt ? new Date(s.createdAt).toLocaleString() : ""}
                    </div>
                  </div>

                  {/* IMPORTANT: className must match your CSS (chat-delete) */}
                  <button
                    type="button"
                    title="Delete chat"
                    aria-label={`Delete chat ${summaryOf(s)}`}
                    className="chat-delete"
                    onClick={(ev) => {
                      ev.stopPropagation();
                      ev.preventDefault();
                      openConfirm(id, summaryOf(s));
                      // debug
                      console.log("openConfirm for", id);
                    }}
                  >
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                      <path d="M3 6h18" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/>
                      <path d="M8 6v12a2 2 0 0 0 2 2h4a2 2 0 0 0 2-2V6" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/>
                      <path d="M10 11v6" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/>
                      <path d="M14 11v6" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                  </button>
                </div>
              );
            })
          )}
        </div>

        <div style={{ fontWeight: 700, color: "#0f172a", marginTop: 6 }}>Navigation</div>

        <nav className="nav-list" aria-label="Primary navigation">
          <Link to="/flights" className={`nav-link ${location.pathname === "/flights" ? "active" : ""}`}>
            <span className="nav-ico">✈️</span>
            <span className="nav-text">Flight Search</span>
          </Link>
          <Link to="/hotels" className={`nav-link ${location.pathname === "/hotels" ? "active" : ""}`}>
            <span className="nav-ico">🏨</span>
            <span className="nav-text">Hotels & Cuisines</span>
          </Link>
          <Link to="/news" className={`nav-link ${location.pathname === "/news" ? "active" : ""}`}>
            <span className="nav-ico">📰</span>
            <span className="nav-text">Travel News & Blogs</span>
          </Link>
        </nav>
      </div>

      <div className="sidebar-footer">
        <ProfileMenu />
      </div>

      <ConfirmModal
        open={confirmState.open}
        title="Permanently delete this chat?"
        message={`This will permanently remove "${confirmState.title}" from your saved chats.`}
        confirmLabel="Delete"
        cancelLabel="Cancel"
        loading={confirmState.loading}
        error={confirmState.error}
        onCancel={() => closeConfirm()}
        onConfirm={() => handleConfirmDelete()}
      />
    </aside>
  );
}
